import{_ as i,C as r,o as h,c as n,j as e,a as t,E as o,a5 as c}from"./chunks/framework.BYIUCCsM.js";const P=JSON.parse('{"title":"布局","description":"","frontmatter":{},"headers":[],"relativePath":"components/layout.md","filePath":"components/layout.md","lastUpdated":1787598366000}'),s={name:"components/layout.md"},u={id:"布局",tabindex:"-1"};function p(b,d,x,g,y,f){const l=r("Badge"),a=r("XhDemo");return h(),n("div",null,[e("h1",u,[d[0]||(d[0]=t("布局 ",-1)),o(l,{type:"info",text:"layout"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#布局","aria-label":'Permalink to "布局 <Badge type="info" text="layout" />"'},"​",-1))]),d[3]||(d[3]=c('<p>一整页的骨架：头与脚各横贯一行，侧栏与内容并排占中间那一行。少写一段就少一行或少一列。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>搭一个应用外壳：管理后台、控制台、文档站。</li><li>侧栏需要折叠，且折叠时节点仍在（只改宽度，不卸载）。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是把几个块并排：用<a href="./flex">弹性布局</a>或<a href="./grid">栅格</a>。</li><li>两块区域之间要由用户拖动分配空间：用<a href="./splitter">分栏</a>。</li><li>侧栏本身是一棵可展开的导航树：布局只出壳，树交给<a href="./side-nav">侧栏导航</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>六个部件都可选，只写用得上的那几段。</li><li>折叠只改宽度，侧栏节点一直在：里面的滚动位置与焦点不会丢。</li><li>展开与折叠各一档宽度，两档都接受任意 CSS 长度。</li><li><code>headerFixed</code> 与 <code>siderFixed</code> 各自独立；两个一起用时侧栏自动让开头的高度。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>头与脚各横贯一行，侧栏与内容并排占中间那一行；少写一段就少一行或少一列</p>',10)),o(a,{src:"layout/01-basic"}),d[4]||(d[4]=e("h3",{id:"折叠侧栏",tabindex:"-1"},[t("折叠侧栏 "),e("a",{class:"header-anchor",href:"#折叠侧栏","aria-label":'Permalink to "折叠侧栏"'},"​")],-1)),d[5]||(d[5]=e("p",null,"不传 sider-collapsed 即为非受控，把手按下去只改宽度，侧栏节点一直在",-1)),o(a,{src:"layout/02-sider-collapse"}),d[6]||(d[6]=e("h3",{id:"受控",tabindex:"-1"},[t("受控 "),e("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[7]||(d[7]=e("p",null,"传了 sider-collapsed 就由宿主说了算，组件不再自改，只发 sider-collapsed-change",-1)),o(a,{src:"layout/03-controlled"}),d[8]||(d[8]=e("h3",{id:"侧栏位置",tabindex:"-1"},[t("侧栏位置 "),e("a",{class:"header-anchor",href:"#侧栏位置","aria-label":'Permalink to "侧栏位置"'},"​")],-1)),d[9]||(d[9]=e("p",null,"sider-placement 决定侧栏挂在行首还是行尾，分隔线也跟着换到挨内容的那一边",-1)),o(a,{src:"layout/04-sider-placement"}),d[10]||(d[10]=e("h3",{id:"侧栏宽度",tabindex:"-1"},[t("侧栏宽度 "),e("a",{class:"header-anchor",href:"#侧栏宽度","aria-label":'Permalink to "侧栏宽度"'},"​")],-1)),d[11]||(d[11]=e("p",null,"展开与折叠各一档宽度，两档都接受任意 CSS 长度，切换时按皮肤里的过渡走",-1)),o(a,{src:"layout/05-sider-width"}),d[12]||(d[12]=e("h3",{id:"吸顶与固定",tabindex:"-1"},[t("吸顶与固定 "),e("a",{class:"header-anchor",href:"#吸顶与固定","aria-label":'Permalink to "吸顶与固定"'},"​")],-1)),d[13]||(d[13]=e("p",null,"header-fixed 让头钉在滚动容器上沿，sider-fixed 让侧栏跟着钉住；两个一起用时侧栏自动让开头的高度",-1)),o(a,{src:"layout/06-fixed"}),d[14]||(d[14]=e("h3",{id:"分别固定",tabindex:"-1"},[t("分别固定 "),e("a",{class:"header-anchor",href:"#分别固定","aria-label":'Permalink to "分别固定"'},"​")],-1)),d[15]||(d[15]=e("p",null,"两个开关各自独立：只写 header-fixed 时侧栏照常随内容滚走，只写 sider-fixed 时侧栏钉在滚动容器上沿、头照常滚走",-1)),o(a,{src:"layout/07-fixed-independent"}),d[16]||(d[16]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-layout&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhLayoutContent</code> <code>XhLayoutFooter</code> <code>XhLayoutHeader</code> <code>XhLayoutRoot</code> <code>XhLayoutSider</code> <code>XhLayoutSiderTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useLayout</code></td></tr><tr><td>状态机</td><td><code>layoutMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/layout.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;layout&quot;</code>：<strong><code>root</code></strong> · <code>header</code> · <code>sider</code> · <code>content</code> · <code>footer</code> · <code>sider-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>siderCollapsed</code></td><td><code>boolean</code></td><td></td><td>受控折叠态：给了值就由宿主说了算。</td></tr><tr><td><code>defaultSiderCollapsed</code></td><td><code>boolean</code></td><td></td><td>非受控初始折叠态。</td></tr><tr><td><code>siderWidth</code></td><td><code>string</code></td><td></td><td>展开时侧栏的宽度，任意 CSS 长度；不写则用皮肤里的档位。</td></tr><tr><td><code>siderCollapsedWidth</code></td><td><code>string</code></td><td></td><td>折叠时侧栏的宽度，任意 CSS 长度；不写则用皮肤里的档位。</td></tr><tr><td><code>siderPlacement</code></td><td><code>LayoutSiderPlacement</code></td><td></td><td>侧栏挂在行首还是行尾，缺省 start。</td></tr><tr><td><code>headerFixed</code></td><td><code>boolean</code></td><td></td><td>头吸顶：滚动时头钉在滚动容器的上沿。只落标记，钉住的实现归皮肤。</td></tr><tr><td><code>siderFixed</code></td><td><code>boolean</code></td><td></td><td>侧栏吸附：滚动时侧栏钉在滚动容器的上沿，头也吸顶时让开头那一条。只落标记，钉住的实现归皮肤。</td></tr><tr><td><code>bordered</code></td><td><code>boolean</code></td><td></td><td>在头、侧栏、脚与内容之间画分隔线。</td></tr><tr><td><code>onSiderCollapsedChange</code></td><td><code>(details: LayoutSiderCollapsedChangeDetails) =&gt; void</code></td><td></td><td>折叠态变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>sider-collapsed-change</code></td><td><code>LayoutSiderCollapsedChangeDetails</code></td><td>折叠态变化；detail 为 <code>{ collapsed: boolean }</code></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>expanded</code> · <code>collapsed</code></p><p><strong>事件</strong>：<code>SIDER.COLLAPSE</code> · <code>SIDER.EXPAND</code> · <code>SIDER.TOGGLE</code> · <code>CONTROLLED.COLLAPSE</code> · <code>CONTROLLED.EXPAND</code></p><p><strong>判据</strong>：<code>isSiderCollapsedControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useLayout</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>siderCollapsed</code></td><td><code>boolean</code></td><td>侧栏当前是否折叠。</td></tr><tr><td><code>setSiderCollapsed</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSiderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getFooterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSiderTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Space</code> / <code>Enter</code></td><td>focus in sider-trigger</td><td>折叠/展开 sider</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>sider-trigger</code></td><td><code>aria-controls</code></td><td><code>sider</code> 部件的 id</td></tr><tr><td><code>sider-trigger</code></td><td><code>aria-expanded</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/layout.css</code> 按部件选择：<code>[data-scope=&quot;layout&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-bordered</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-header-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-sider-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-sider-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-sider-placement</code></td><td>props.siderPlacement</td></tr><tr><td><code>header</code></td><td><code>data-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>sider</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>sider</code></td><td><code>data-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>sider</code></td><td><code>data-placement</code></td><td>props.siderPlacement</td></tr><tr><td><code>sider-trigger</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-layout-bg</code> · <code>--xh-layout-border</code> · <code>--xh-layout-content-padding</code> · <code>--xh-layout-fg</code> · <code>--xh-layout-footer-bg</code> · <code>--xh-layout-footer-padding</code> · <code>--xh-layout-header-bg</code> · <code>--xh-layout-header-gap</code> · <code>--xh-layout-header-h</code> · <code>--xh-layout-header-layer</code> · <code>--xh-layout-header-px</code> · <code>--xh-layout-scrollport-h</code> · <code>--xh-layout-sider-bg</code> · <code>--xh-layout-sider-collapsed-width</code> · <code>--xh-layout-sider-padding</code> · <code>--xh-layout-sider-trigger-bg</code> · <code>--xh-layout-sider-trigger-bg-hover</code> · <code>--xh-layout-sider-trigger-fg</code> · <code>--xh-layout-sider-trigger-gap</code> · <code>--xh-layout-sider-trigger-px</code> · <code>--xh-layout-sider-trigger-radius</code> · <code>--xh-layout-sider-width</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li><code>sider</code> 里放<a href="./side-nav">侧栏导航</a>，<code>header</code> 里放<a href="./menubar">菜单栏</a>或<a href="./toolbar">工具栏</a>，<code>content</code> 里放<a href="./page-header">页头</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>内容区自己定高、内部滚动，别让整页滚动——吸顶的头与侧栏才立得住。</li><li>折叠态的宽度要放得下图标加内边距，否则图标会被裁。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>折叠时把侧栏整个卸载再挂回来：展开的分支、滚动位置、焦点全部重置。</li><li>头和侧栏都不吸附却给它们设了 <code>position: fixed</code>：占位没了，内容会被盖住。</li></ul>',43))])}const q=i(s,[["render",p]]);export{P as __pageData,q as default};
